# -*- coding: utf-8 -*-
"""Record partial official evidence; approved Commons originals already downloaded."""
import io, json, os
import ca50_gaps as G
from ca50_gaps import L
D='2026-10-24'
h, records, t = G.load()
u={r['id']:r for r in records}
src='https://www.capilanou.ca/media/capilanouca/programs-amp-courses/capu-for-you/international-students/EQU-INTL-SEC-CURRICULA-202120-Web.pdf'
u['capilano-university']['academics'].update(G.plain({
    'internationalQualifications': L('Uzbekistan: Capilano’s currently linked international secondary-school equivalency list (2021 file), page 10, names O’rta Ma’lumot To’g’risida Shahodatnoma or Attestat o Srednem Obrazovanii. The table establishes a school-completion equivalency only; required grades, programme subjects and any preparatory study for a specific applicant are not established. No 2027 cycle is stated.', 'Узбекистан: действующая ссылка Capilano ведёт на таблицу школьных эквивалентов (файл 2021), стр. 10: O’rta Ma’lumot To’g’risida Shahodatnoma или Attestat o Srednem Obrazovanii. Таблица подтверждает лишь эквивалент окончания школы; оценки, предметы программы и возможная подготовка для конкретного абитуриента не установлены. Набор 2027 не указан.'),
    'internationalQualificationsSource': src, 'internationalQualificationsVerified': D}))
G.source(u['capilano-university'], 'Capilano — international secondary-school equivalencies', src)

# A reviewed page can leave the general policy unknown. In particular, a
# homeschool or English-language alternative is not a universal admissions rule.
reviews=[
('university-of-ottawa','https://www.uottawa.ca/study/undergraduate-studies/international-applicants/usa',L('The official US-curriculum page (American high schools in the US or abroad) lists Grade 12, admission average and programme prerequisites, but does not explicitly establish a SAT/ACT submission policy. Requirements for other school systems and the 2027 policy remain unconfirmed.', 'Официальная страница американской школьной программы (в США и за рубежом) перечисляет Grade 12, среднюю оценку и предметы программы, но явно не устанавливает политику подачи SAT/ACT. Требования других школьных систем и политика 2027 остаются неподтверждёнными.')),
('university-of-saskatchewan','https://admissions.usask.ca/requirements/home-based.php',L('For home-based learners only, USask accepts independent SAT I results from 1100 or ACT average 24 as assessment tools, alongside programme prerequisites and the college admission average. These scoped alternatives do not establish a general SAT/ACT requirement or a 2027 test-optional policy for other school systems.', 'Только для домашнего обучения USask принимает независимую оценку SAT I от 1100 или средний ACT 24 вместе с предметными требованиями и средней оценкой колледжа. Эти специальные варианты не устанавливают общее требование SAT/ACT или test-optional политику 2027 для других школьных систем.')),
('brock-university','https://brocku.ca/webcal/current/undergrad/admi.html',L('The accessible calendar page is labelled 2024–2025; it does not establish the 2027 SAT/ACT policy. A current handbook request returned 403. The general policy remains unconfirmed; older US-school and homeschool statements are not applied to all applicants.', 'Доступная страница календаря обозначена 2024–2025 и не подтверждает SAT/ACT на 2027. Запрос текущего handbook вернул 403. Общая политика остаётся неподтверждённой; старые условия для американских школ и домашнего обучения не переносятся на всех.')),
('wilfrid-laurier-university','https://www.wlu.ca/future-students/undergraduate/admissions/assets/resources/sat-act-curriculum.html',L('The SAT/ACT Curriculum page explicitly says ACT and SAT subject exams may support a homeschooled application but are not required. This is a homeschool statement, not a universal policy for American or Uzbek school qualifications; the general and 2027 policies remain unconfirmed.', 'Страница SAT/ACT Curriculum прямо говорит, что ACT и предметные SAT могут дополнять заявку с домашним обучением, но не обязательны. Это условие для домашнего обучения, а не общая политика для американских или узбекских школьных документов; общая политика и набор 2027 не подтверждены.')),
('acadia-university','https://www2.acadiau.ca/admissions/application-process/american-students.html',L('The official American-student requirements page was read; no explicit general SAT/ACT submission policy was established. An omitted test on this page is not evidence of a test-optional rule for every school system or faculty.', 'Официальная страница требований к американским абитуриентам прочитана; явная общая политика подачи SAT/ACT не установлена. Отсутствие теста на странице не доказывает test-optional правило для каждой школьной системы или факультета.')),
('saint-marys-university','https://www.smu.ca/future-students/admissions/internationaladmissions/',L('The international-admission page describes US-patterned high-school subjects and grades without establishing an explicit SAT/ACT policy. Other curricula, programme exceptions and the 2027 cycle remain unconfirmed; this is not recorded as test-optional.', 'Международная страница описывает предметы и оценки американской школьной программы, но не устанавливает явную политику SAT/ACT. Другие системы, исключения программ и цикл 2027 не подтверждены; test-optional не присваивается.')),
('mount-royal-university','https://www.mtroyal.ca/InternationalStudents/Admissionrequirements/index.htm',L('The official international-admission page was reviewed. It requires general and programme-specific admission conditions but does not establish an explicit SAT/ACT policy by school system. General policy remains unconfirmed.', 'Проверена официальная страница международного приёма. Она требует выполнения общих и предметных условий, но не устанавливает явную политику SAT/ACT по школьным системам. Общая политика остаётся неподтверждённой.')),
('university-of-northern-british-columbia','https://www.unbc.ca/programs-and-admissions/undergraduate/international-admission-requirements-undergraduate-studies',L('The current country-requirements page links US secondary-school qualifications and subject requirements but does not establish an explicit general SAT/ACT policy. The 2027 policy and faculty exceptions remain unconfirmed.', 'Текущая страница страновых требований связывает американскую школьную квалификацию и предметные требования, но не устанавливает явную общую политику SAT/ACT. Политика 2027 и исключения факультетов остаются неподтверждёнными.')),
('vancouver-island-university','https://www.viu.ca/admissions/international',L('The official international-admission and high-school equivalency page was reviewed; an explicit SAT/ACT policy for admission was not established. English proficiency alternatives and school-completion equivalencies do not prove a universal test-optional policy.', 'Проверена официальная страница международного приёма и школьных эквивалентов; явная политика SAT/ACT для поступления не установлена. Языковые альтернативы и школьные эквиваленты не доказывают всеобщую test-optional политику.')),
('university-of-the-fraser-valley','https://international.ufv.ca/future-students/apply-to-ufv/admission-requirements/',L('The international-admission page requires Grade-12-equivalent qualifications, English proficiency and programme prerequisites; it does not explicitly establish a SAT/ACT submission policy. Policy by school system and programme remains unconfirmed.', 'Международная страница требует эквивалент Grade 12, английский и предметы программы, но не устанавливает явно политику подачи SAT/ACT. Политика по школьным системам и программам остаётся неподтверждённой.')),
('laurentian-university','https://laurentian.ca/academics/admissions/international/undergraduate-admissions',L('The current international page lists a US high-school diploma with B average or better and separate faculty prerequisites. It does not explicitly establish the SAT/ACT policy; this omission is not treated as a universal test-optional rule.', 'Текущая международная страница перечисляет американский школьный диплом со средней B или выше и отдельные предметные требования факультетов. Она не устанавливает явно политику SAT/ACT; отсутствие упоминания не считается всеобщей test-optional политикой.'))
]
for uid,src,note in reviews:
    for key in ('sat','act'):
        assert u[uid]['academics'][key]['policy'] is None
        u[uid]['academics'][key].update(G.plain({'note':note,'source':src,'verified':D}))
    G.source(u[uid], 'SAT/ACT scope review — general policy unresolved', src)
wi=u['university-of-windsor']['admissions']['applicationFee']
assert wi['amount'] is None
wi.update(G.plain({'source':'https://future.uwindsor.ca/apply-international','verified':D,
    'note':L('Rechecked: the official direct international application and Finance fees pages do not establish the application charge for this applicant route. The C$2,000 enrolment deposit and graduate application fees are different charges. Application fee remains unknown.', 'Перепроверено: официальные страницы прямой международной заявки и сборов Finance не устанавливают стоимость заявки для этого маршрута. Депозит C$2,000 и сборы graduate — другие платежи. Application fee остаётся неизвестным.')}))
G.save(h,records,t)

photos={
'olin-college-of-engineering':{'src':'assets/img/universities/olin-college-of-engineering/1.jpg','title':L('Olin College Great Lawn','Большая лужайка Olin College'),'caption':L('Olin College campus and Great Lawn — historic photograph, taken in 2002; original retained without changes','Кампус Olin College и большая лужайка — исторический снимок 2002 года; оригинал сохранён без изменений'),'artist':'Michael Maloney','license':'CC BY-SA 3.0','licenseUrl':'https://creativecommons.org/licenses/by-sa/3.0/','page':'https://commons.wikimedia.org/wiki/File:Olin_College_Great_Lawn.jpg','verified':D},
'temple-university-japan':{'src':'assets/img/universities/temple-university-japan/1.jpg','title':L('Temple University Japan — Setagaya','Temple University Japan — Setagaya'),'caption':L('Temple University Japan, Tokyo campus at Showa Women’s University, 26 July 2019; original retained without changes (320 × 240 pixels)','Temple University Japan, кампус Tokyo при Showa Women’s University, 26 июля 2019; оригинал сохранён без изменений (320 × 240 пикселей)'),'artist':'Temple University Japan','license':'CC BY-SA 4.0','licenseUrl':'https://creativecommons.org/licenses/by-sa/4.0/','page':'https://commons.wikimedia.org/wiki/File:TUJ_Setagaya.jpg','verified':D}}
p=os.path.join(G.ROOT,'data/photos.js');s=io.open(p,encoding='utf8').read()
assert all(('"'+uid+'"') not in s for uid in photos)
rows=''.join('  '+json.dumps(uid)+': '+json.dumps([G.plain(photo)],ensure_ascii=False)+',\n' for uid,photo in photos.items())
s=s.replace('window.UNIPATH.photos = {','window.UNIPATH.photos = {\n'+rows)
io.open(p,'w',encoding='utf8').write(s)
G.flush()
